DROP TABLE IF EXISTS "form_submissions" CASCADE;

CREATE TABLE "form_submissions" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "form_submissions_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"event_date" text NOT NULL,
	"confirm_date" text NOT NULL,
	"company_name" text NOT NULL,
	"relationship_type" text NOT NULL,
	"request_category" text NOT NULL,
	"client_name" text NOT NULL,
	"id_number" text NOT NULL,
	"description" text NOT NULL,
	"sale_amount" text NOT NULL,
	"cost_amount" text NOT NULL,
	"email" text NOT NULL,
	"emails" json NOT NULL,
	"phone" text NOT NULL,
	"region" text NOT NULL,
	"transport_process" text NOT NULL,
	"process" text NOT NULL,
	"service_type" text NOT NULL,
	"cities" text NOT NULL,
	"channel" text NOT NULL,
	"support_file_url" text,
	"support_file_2_url" text,
	"certificate_file_url" text,
	"value_sheet_file_url" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
